import React from 'react';

const ValidatorDashboard = () => {
  return (
    <div>
      <h1 className="text-2xl font-bold mb-6">Tableau de bord validateur</h1>
      <div className="card">
        <p>Bienvenue. Les demandes a valider apparaitront ici.</p>
      </div>
    </div>
  );
};

export default ValidatorDashboard;
